import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('admin', 'admin@corp.local', 'admin', 'IT')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('jsmith', 'jsmith@corp.local', 'user', 'Sales')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role with optional filters."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    active_only = request.args.get('active', '1')

    # Build query with filters
    conditions = []
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")
    if active_only == '1':
        conditions.append("active = 1")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'
    query = f"SELECT id, username, email, role, department FROM users WHERE {where_clause}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID."""
    db = get_db()
    cursor = db.execute("SELECT id, username, email, role, department FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    username = data['username']
    email = data['email']
    department = data.get('department', 'General')

    # Prevent role escalation - new users are always 'user' role
    role = 'user'

    try:
        db = get_db()
        db.execute(
            "INSERT INTO users (username, email, role, department) VALUES (?, ?, ?, ?)",
            (username, email, role, department)
        )
        db.commit()
        return jsonify({'status': 'created', 'username': username}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
